openai_client.py

A tiny, standard-library-only client for OpenAI\\'s Responses API.

- No third-party dependencies.
- Uses "'`OPENAI_API_KEY` from the environment.
- Optional `OPENAI_ORG_ID` and `OPENAI_PROJECT_ID` headers if set.
- Convenience `text()` method returns the aggregated text output.

Basic usage:

    from openai_client import OpenAIClient

    client = OpenAIClient()  # reads OPENAI_API_KEY
    result = client.text(
        prompt="Write a haiku about the sea.",
        model="gpt-4.1-mini",  # or use OPENAI_MODEL env var
    )
    print(result)

CLI usage (reads stdin if no arg):

    python -m openai_client "Explain TCP in one sentence."

Notes on privacy: This module does not log or persist prompts,
responses, or credentials. Errors avoid echoing credential values.
"""
from __future__ import annotations

import json
import os
import sys
import time
import typing as _t
from dataclasses import dataclass
from urllib import request, error


_DEFAULT_MODEL = os.environ.get("OPENAI_MODEL", "gpt-4.1-mini")


@dataclass
class OpenAIClient:
    """Minimal client for the OpenAI Responses API.

    Parameters
    - api_key: API key string. Defaults to env `OPENAI_API_KEY`.
    - base_url: API base, defaults to `https://api.openai.com/v1`.
    - organization: Optional org ID, from `OPENAI_ORG_ID` if omitted.
    - project: Optional project ID, from `OPENAI_PROJECT_ID` if omitted.
    - timeout: Request timeout in seconds (float ok). Default 60.
    """

    api_key: str | None = None
    base_url: str = "https://api.openai.com/v1"
    organization: str | None = None
    project: str | None = None
    timeout: float = 60.0

    def __post_init__(self) -> None:
        if self.api_key is None:
            self.api_key = [REDACTED_SECRET]"OPENAI_API_KEY")
        if not self.api_key:
            raise RuntimeError(
                "Missing OPENAI_API_KEY. Set it in your environment to use OpenAIClient."
            )
        if self.organization is None:
            self.organization = os.environ.get("OPENAI_ORG_ID")
        if self.project is None:
            self.project = os.environ.get("OPENAI_PROJECT_ID")

    # ---------- Public API ----------

    def text(
        self,
        prompt: str,
        model: str | None = None,
        *,
        system: str | None = None,
        temperature: float | None = None,
        extra_body: dict | None = None,
    ) -> str:
        """Send a text prompt and return aggregated text output.

        Arguments
        - prompt: The user input text.
        - model: Model name. Defaults to env `OPENAI_MODEL` or `_DEFAULT_MODEL`.
        - system: Optional system instructions string.
        - temperature: Optional temperature.
        - extra_body: Extra JSON fields to merge into the request body.

        Returns the response'"\\'s best-effort text aggregation.
        Raises "'`HTTPError` or `URLError` for network failures.
        """
        resp = self.create_response(
            prompt=prompt,
            model=model or _DEFAULT_MODEL,
            system=system,
            temperature=temperature,
            extra_body=extra_body,
        )
        return self.extract_text(resp)

    def create_response(
        self,
        *,
        prompt: str,
        model: str,
        system: str | None = None,
        temperature: float | None = None,
        extra_body: dict | None = None,
    ) -> dict:
        """Call POST /responses and return parsed JSON dict.

        This uses the simple form of the Responses API with `input`.
        `system` maps to `instructions`.
        """
        body: dict[str, _t.Any] = {"model": model, "input": prompt}
        if system:
            body["instructions"] = system
        if temperature is not None:
            body["temperature"] = temperature
        if extra_body:
            body.update(extra_body)

        return self._post_json("/responses", body)

    # ---------- Helpers ----------

    def extract_text(self, response: dict) -> str:
        """Best-effort text extraction across current/future shapes.

        Priority order:
        1) `output_text` convenience string
        2) Concatenate any text within `output[*].content[*].text`
        3) Fallback to Chat Completions-like `choices[0].message.content`
        4) Last resort: empty string
        """
        # 1) Direct convenience field (common in Responses API)
        if isinstance(response, dict):
            ot = response.get("output_text")
            if isinstance(ot, str) and ot.strip():
                return ot

        # 2) Walk `output` -> `content` parts for text-like fields
        try:
            output = response.get("output")
            if isinstance(output, list):
                parts: list[str] = []
                for item in output:
                    content = item.get("content") if isinstance(item, dict) else None
                    if isinstance(content, list):
                        for part in content:
                            if not isinstance(part, dict):
                                continue
                            # Likely shapes: {"type": "output_text", "text": "..."}
                            text_val = part.get("text")
                            if isinstance(text_val, str):
                                parts.append(text_val)
                if parts:
                    return "".join(parts).strip()
        except Exception:
            pass

        # 3) Fallback: legacy Chat Completions-like shape
        try:
            choices = response.get("choices")
            if isinstance(choices, list) and choices:
                msg = choices[0].get("message")
                if isinstance(msg, dict):
                    content = msg.get("content")
                    if isinstance(content, str):
                        return content.strip()
        except Exception:
            pass

        return ""

    # ---------- Low-level HTTP ----------

    def _headers(self) -> dict[str, str]:
        h = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        }
        if self.organization:
            # Historical header name used by OpenAI
            h["OpenAI-Organization"] = self.organization
        if self.project:
            # Project scoping when applicable
            h["OpenAI-Project"] = self.project
        return h

    def _post_json(self, path: str, body: dict) -> dict:
        url = self.base_url.rstrip("/") + path
        data = json.dumps(body).encode("utf-8")
        req = request.Request(url=url, data=data, headers=self._headers(), method="POST")
        try:
            with request.urlopen(req, timeout=self.timeout) as resp:
                ctype = resp.headers.get("Content-Type", "application/json")
                raw = resp.read()
                if "application/json" in ctype:
                    return json.loads(raw.decode("utf-8"))
                # If server returns non-JSON, still return something usable
                return {"raw": raw.decode("utf-8", errors="replace"), "status": resp.status}
        except error.HTTPError as e:
            # Attempt to decode JSON error while avoiding key leakage
            detail = _safe_decode_error(e, redact=self._redact)
            raise error.HTTPError(
                e.url, e.code, detail, e.headers, e.fp
            ) from None
        except error.URLError as e:
            msg = str(e.reason) if hasattr(e, "reason") else str(e)
            raise error.URLError(self._redact(msg)) from None

    def _redact(self, s: str) -> str:
        """Redact API key if it appears in `s`."""
        if not s:
            return s
        key = self.api_key or ""
        if key and key in s:
            # Preserve prefix shape a bit while hiding majority
            return s.replace(key, key[:6] + "…REDACTED…")
        return s


def _safe_decode_error(e: error.HTTPError, redact: _t.Callable[[str], str]) -> str:
    """Decode an HTTPError body, prefer JSON `error.message` if present."""
    try:
        raw = e.read()
    except Exception:
        raw = b""
    try:
        payload = json.loads(raw.decode("utf-8")) if raw else {}
    except Exception:
        payload = {}

    # OpenAI-style error envelope
    if isinstance(payload, dict):
        err = payload.get("error")
        if isinstance(err, dict):
            msg = err.get("message") or err.get("code") or str(err)
            return redact(str(msg))
        # Responses API sometimes returns error details top-level
        for k in ("message", "error_message", "detail"):
            if k in payload and isinstance(payload[k], str):
                return redact(payload[k])

    # Fallback: status line + body (redacted)
    snippet = raw.decode("utf-8", errors="replace") if raw else ""
    base = f"HTTP {e.code} while calling {e.url}"
    if snippet:
        return redact(f"{base}: {snippet}")
    return redact(base)


# -------- CLI entrypoint --------

def _read_stdin_all() -> str:
    try:
        if sys.stdin and not sys.stdin.isatty():
            return sys.stdin.read()
    except Exception:
        pass
    return ""


def main(argv: list[str] | None = None) -> int:
    argv = list(sys.argv[1:] if argv is None else argv)
    if argv:
        prompt = " ".join(argv).strip()
    else:
        prompt = _read_stdin_all().strip()
    if not prompt:
        print("Usage: python -m openai_client <prompt> | echo <prompt> | python -m openai_client", file=sys.stderr)
        return 2

    model = os.environ.get("OPENAI_MODEL", _DEFAULT_MODEL)
    try:
        client = OpenAIClient()
        t0 = time.time()
        text = client.text(prompt, model=model)
        dt = time.time() - t0
        print(text)
        # Timing to stderr so stdout stays clean
        print(f"[openai_client] {len(text)} chars in {dt:.2f}s via {model}", file=sys.stderr)
        return 0
    except Exception as exc:  # Keep CLI terse and private
        print(f"Error: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
